       "offset_months": -1,
       "day": "last"
      }
     }
    }
   },
   "condition": {
    "exists": {
     "event": "SALARY_TRANSFER",
     "within": {
      "ref": "$window"
     }
    }
   },
   "effect": {
    "type": "FEE_WAIVE",
    "target": "ATM_WITHDRAW_AFTER_HOURS",
    "value": "UNLIMITED"
   }
  },
  {
   "rule_id": "R-EX-02-03",
   "status": "OK",
